import {useCallback,useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import {Link,NavLink,Navigate,Route,Routes,useLocation,useNavigate,useParams,useSearchParams} from 'react-router-dom';
import {ArrowLeft,ArrowRight,ArrowUpLeft,CalendarDays,Check,CheckCircle2,ChevronLeft,Clock,Download,ExternalLink,FileSpreadsheet,Home,Info,LogIn,LogOut,MapPin,Menu,Plus,ScanLine,Search,ShieldCheck,Sparkles,Ticket as TicketIcon,UserRound,Users, X,AlertTriangle,ImagePlus,RefreshCw,ClipboardCheck,CalendarCheck,Lock,Smartphone,LayoutDashboard,Camera,BookOpen} from 'lucide-react';
import {QRCodeSVG} from 'qrcode.react';
import {AuthProvider,useAuth} from './Auth';
import {asSaudiUTC,authHeader,bookingLabel,bookingTone,configured,dateLong,db,demoEvents,isDemo,localSaudi,paymentLabel,safeError,sar,timeSA,type Booking,type EventData,type Ticket as TicketData} from './lib';

function useToast(){const [message,setMessage]=useState('');useEffect(()=>{if(!message)return;const t=setTimeout(()=>setMessage(''),5300);return()=>clearTimeout(t)},[message]);return {message,notify:setMessage};}
function Shell({children}:{children:ReactNode}){const {user,role,loading}=useAuth();const [menu,setMenu]=useState(false);const {pathname}=useLocation();const navigate=useNavigate();useEffect(()=>{setMenu(false);window.scrollTo({top:0,behavior:'auto'})},[pathname]);const admin=pathname.startsWith('/admin');return <><header className="site-header"><div className="header-inner"><Link to="/" className="brand" aria-label="تيوزدية الصفحة الرئيسية"><img src="/logo.webp" alt="تيوزدية ريادة الأعمال"/><span>مجتمع يصنع فرصًا</span></Link><nav className="desktop-nav"><NavLink to="/" end>الرئيسية</NavLink><NavLink to="/events">الورش واللقاءات</NavLink><NavLink to="/about">عن تيوزدية</NavLink>{role&&<NavLink to="/admin">لوحة الإدارة</NavLink>}</nav><div className="header-actions">{user?<Link className="header-user" to="/account"><UserRound size={18}/><span>حسابي</span></Link>:<Link className="header-user" to="/login"><LogIn size={18}/><span>دخول</span></Link>}<button aria-label="القائمة" className="icon-button menu-button" onClick={()=>setMenu(!menu)}><Menu size={23}/></button></div></div>{menu&&<nav className="dropdown-nav"><Link to="/">الرئيسية</Link><Link to="/events">جميع الورش</Link><Link to="/about">عن تيوزدية</Link><Link to={user?'/account':'/login'}>حسابي</Link>{role&&<Link to="/admin">الإدارة</Link>}</nav>}</header>{!configured&&<div className="demo-strip"><Info size={15}/><span>وضع العرض: اربط Supabase لتفعيل الحسابات والحجوزات الفعلية. البيانات المعروضة أمثلة.</span></div>}<main className={admin?'main admin-main':'main'}>{loading?<div className="loading-page"><div className="spinner"/>جارٍ التحميل...</div>:children}</main><footer className="site-footer"><img src="/logo.webp" alt="تيوزدية"/><p>لقاءات تجمع روّاد الأعمال، وأفكار تفتح آفاقًا جديدة.</p><div><Link to="/about">عن المجتمع</Link><Link to="/privacy">الخصوصية والشروط</Link><Link to="/events">الورش</Link></div><small>© {new Date().getFullYear()} تيوزدية ريادة الأعمال</small></footer><nav className="bottom-nav" aria-label="التنقل الرئيسي"><NavLink to="/" end><Home size={21}/><span>الرئيسية</span></NavLink><NavLink to="/events"><CalendarDays size={21}/><span>الورش</span></NavLink><NavLink to="/account"><TicketIcon size={21}/><span>تذاكري</span></NavLink><NavLink to={role?'/admin':'/about'}>{role?<LayoutDashboard size={21}/>:<Users size={21}/>}<span>{role?'الإدارة':'عنّا'}</span></NavLink></nav></>}
function Pill({children,tone='blue'}:{children:ReactNode;tone?:string}){return <span className={'pill '+tone}>{children}</span>}
function SectionTitle({eyebrow,title,desc}:{eyebrow?:string;title:string;desc?:string}){return <div className="section-heading"><div>{eyebrow&&<p className="eyebrow">{eyebrow}</p>}<h2>{title}</h2>{desc&&<p className="subtle">{desc}</p>}</div></div>}
function EventVisual({event,large=false}:{event:EventData;large?:boolean}){return <div className={'event-visual '+(large?'large':'')} style={event.image_url?{backgroundImage:`linear-gradient(0deg,rgba(2,14,26,.83),rgba(2,14,26,.04)),url("${event.image_url.replaceAll('"','%22')}")`}:undefined}><div className="visual-glow"/><div className="visual-content"><span className="visual-kicker">TUESDAY ENTREPRENEURSHIP</span><h3>{event.title}</h3><p>{event.subtitle}</p></div><span className="visual-stars">✳</span></div>}
function EventCard({event,compact=false}:{event:EventData;compact?:boolean}){return <Link to={'/events/'+event.slug} className={'event-card '+(compact?'compact':'')}><EventVisual event={event}/><div className="event-card-body"><div className="event-meta-row"><Pill tone={event.price_sar===0?'mint':'blue'}>{sar(event.price_sar)}</Pill><span><CalendarDays size={14}/>{dateLong(event.starts_at)}</span></div><h3>{event.title}</h3><p>{event.subtitle}</p><div className="event-card-bottom"><span><MapPin size={15}/>{event.venue_name||'سيعلن الموقع قريبًا'}</span><span className="round-arrow"><ArrowUpLeft size={18}/></span></div></div>{isDemo(event)&&<span className="demo-flag">ورشة توضيحية</span>}</Link>}
function useEvents(){const [events,setEvents]=useState<EventData[]>(configured?[]:demoEvents);const [loading,setLoading]=useState(configured);const [error,setError]=useState('');const refresh=useCallback(async()=>{if(!db){setEvents(demoEvents);return}setLoading(true);const {data,error}=await db.from('events').select('*').eq('status','published').order('starts_at',{ascending:true});if(error)setError(error.message);else setEvents((data??[]) as EventData[]);setLoading(false)},[]);useEffect(()=>{void refresh()},[refresh]);return {events,loading,error,refresh}}
function InstallBar(){const [deferred,setDeferred]=useState<{prompt:()=>Promise<void>;userChoice:Promise<{outcome:string}>}|null>(null);const [open,setOpen]=useState(false);const [installed,setInstalled]=useState(false);useEffect(()=>{const handler=(e:Event)=>{e.preventDefault();setDeferred(e as Event & {prompt:()=>Promise<void>;userChoice:Promise<{outcome:string}>})};const done=()=>setInstalled(true);window.addEventListener('beforeinstallprompt',handler);window.addEventListener('appinstalled',done);if(window.matchMedia('(display-mode: standalone)').matches)setInstalled(true);return()=>{window.removeEventListener('beforeinstallprompt',handler);window.removeEventListener('appinstalled',done)}},[]);if(installed)return null;return <div className="install-line"><div className="install-icon"><Smartphone size={23}/></div><div><b>تيوزدية على شاشة جوالك</b><p>ادخل لورشِك وتذاكرك بسهولة، بدون تنزيل من المتجر.</p></div><button className="btn btn-mini btn-light" onClick={async()=>{if(deferred){await deferred.prompt();await deferred.userChoice;setDeferred(null)}else setOpen(true)}}>تثبيت</button>{open&&<div className="overlay" onClick={()=>setOpen(false)}><div className="sheet" onClick={e=>e.stopPropagation()}><button className="close-btn" onClick={()=>setOpen(false)}><X/></button><h3>إضافة تيوزدية للشاشة الرئيسية</h3><p>على iPhone: افتح الرابط في Safari، اضغط مشاركة، ثم «إضافة إلى الشاشة الرئيسية».</p><p>على Android: افتح قائمة المتصفح واختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».</p><button className="btn btn-primary" onClick={()=>setOpen(false)}>فهمت</button></div></div>}</div>}
function HomePage(){const {events,loading}=useEvents();const upcoming=events.filter(e=>new Date(e.ends_at).getTime()>Date.now());const feature=upcoming[0]??events[0];return <><section className="hero"><div className="hero-orbit orbit-one"/><div className="hero-orbit orbit-two"/><div className="hero-inner"><div className="hero-badge"><span className="live-dot"/> مجتمع تيوزدية ريادة الأعمال</div><p className="hero-small">كل ثلاثاء، فرصة جديدة</p><h1>أفكار تتلاقى.<br/><em>وفرص تبدأ من هنا.</em></h1><p className="hero-description">لقاءات وورش تجمع الطموح والخبرة في مكان واحد. اكتشف القادم، احجز مقعدك، وابدأ خطوتك التالية.</p><div className="hero-buttons"><Link className="btn btn-sky" to="/events">استكشف اللقاءات <ArrowLeft size={18}/></Link><Link className="btn btn-glass" to="/about">تعرّف علينا</Link></div><div className="hero-mini"><div className="hero-avatars"><span>ت</span><span>ر</span><span>ع</span></div><span>مساحة لصنّاع الأفكار وروّاد الأعمال</span></div></div></section><div className="container"><div className="top-note"><Sparkles size={19}/><span>التعلّم، التواصل، وصناعة الفرص — لقاء واحد ممكن يغيّر اتجاهك.</span></div><section className="section"><div className="section-top"><SectionTitle eyebrow="FEATURED SESSION" title="اللقاء الأبرز"/><Link className="text-link" to="/events">كل الورش <ArrowLeft size={16}/></Link></div>{loading?<div className="skeleton"/>:feature?<EventCard event={feature}/>:<Empty title="ما فيه ورش منشورة حاليًا" desc="ارجع قريبًا للاطلاع على اللقاءات الجديدة."/>}</section><section className="section"><div className="section-top"><SectionTitle eyebrow="WHAT'S NEXT" title="ورش ولقاءات قادمة" desc="اختر اللقاء اللي يضيف لمسارك."/><Link className="text-link" to="/events">عرض الجميع <ArrowLeft size={16}/></Link></div><div className="event-grid">{upcoming.slice(1,5).map(e=><EventCard key={e.id} event={e} compact/>)}</div>{upcoming.length<=1&&!loading&&<div className="small-note">تابع الموقع لظهور لقاءات جديدة.</div>}</section><section className="feature-panel"><div className="feature-logo"><TicketIcon size={32}/></div><div><p className="eyebrow">تذكرتك معك</p><h2>من الحجز إلى الحضور، بخطوة بسيطة.</h2><p>تابع مراجعة طلبك واستلم تذكرة QR عند اعتماد الحجز، ثم أبرزها عند بوابة الدخول.</p><Link className="btn btn-sky" to="/account">شوف حجوزاتك <ArrowLeft size={17}/></Link></div></section><section className="section"><SectionTitle eyebrow="YOUR COMMUNITY" title="ليش تيوزدية؟"/><div className="feature-grid"><div className="info-card"><Users/><h3>ناس تشبه طموحك</h3><p>التقِ بروّاد أعمال ومهتمين بالمشاريع في بيئة تفاعلية.</p></div><div className="info-card"><BookOpen/><h3>معرفة قابلة للتطبيق</h3><p>جلسات متنوعة تساعدك في بناء وتطوير مشروعك.</p></div><div className="info-card"><CalendarCheck/><h3>حجز سهل وواضح</h3><p>تسجيل، متابعة الطلب، وتذكرة رقمية عند الموافقة.</p></div></div></section><InstallBar/></div></>}
function Empty({title,desc}:{title:string;desc?:string}){return <div className="empty"><Sparkles size={28}/><h3>{title}</h3>{desc&&<p>{desc}</p>}</div>}
function EventsPage(){const {events,loading}=useEvents();const [filter,setFilter]=useState<'all'|'free'|'paid'>('all');const [q,setQ]=useState('');const filtered=events.filter(e=>(filter==='all'||(filter==='free'?e.price_sar===0:e.price_sar>0))&&(`${e.title} ${e.subtitle} ${e.speaker}`).toLowerCase().includes(q.toLowerCase()));return <div className="container page-pad"><PageHeader kicker="OUR EVENTS" title="الورش واللقاءات" desc="كل لقاء، فرصة تتعلم فيها شيء جديد وتقابل أشخاص يشاركونك الشغف."/><div className="search-box"><Search size={20}/><input aria-label="ابحث عن ورشة" placeholder="ابحث عن ورشة أو متحدث..." value={q} onChange={e=>setQ(e.target.value)}/></div><div className="tabs">{([['all','جميع اللقاءات'],['free','مجانية'],['paid','مدفوعة']] as const).map(([v,label])=><button key={v} className={filter===v?'active':''} onClick={()=>setFilter(v)}>{label}</button>)}</div>{loading?<div className="skeleton"/>:<div className="event-grid">{filtered.map(e=><EventCard event={e} key={e.id} compact/>)}</div>}{!loading&&filtered.length===0&&<Empty title="ما لقينا ورش مطابقة" desc="جرب تغيير الفلتر أو البحث بكلمة ثانية."/>}</div>}
function PageHeader({kicker,title,desc}:{kicker?:string;title:string;desc?:string}){return <div className="page-header">{kicker&&<span className="eyebrow">{kicker}</span>}<h1>{title}</h1>{desc&&<p>{desc}</p>}</div>}
function EventDetailPage(){const {slug}=useParams();const {events,loading}=useEvents();const event=events.find(e=>e.slug===slug);const {user,profile}=useAuth();const navigate=useNavigate();const {notify,message}=useToast();const [busy,setBusy]=useState(false);const [done,setDone]=useState(false);if(loading)return <div className="container page-pad"><div className="skeleton"/></div>;if(!event)return <div className="container page-pad"><Empty title="هذه الورشة غير متاحة"/><Link to="/events" className="btn btn-primary">العودة للورش</Link></div>;async function book(){if(!event)return;if(isDemo(event)||!db){notify('هذه ورشة توضيحية. اربط قاعدة البيانات وأنشئ ورشة حقيقية أولًا.');return}if(!user){navigate('/login?next='+encodeURIComponent('/events/'+event.slug));return}if(!profile||profile.full_name==='مشارك جديد'||!profile.phone){notify('أكمل اسمك ورقم جوالك في حسابي ثم احجز');navigate('/account');return}setBusy(true);const {error}=await db.rpc('create_booking',{p_event:event.id});setBusy(false);if(error){notify(safeError(error));return}setDone(true)}return <div className="container detail-page"><Link className="back-link" to="/events"><ArrowRight size={18}/> رجوع إلى الورش</Link><div className="detail-layout"><div><EventVisual event={event} large/>{isDemo(event)&&<div className="warn-box"><Info size={17}/> هذه الورشة مثال للعرض فقط ولا تقبل حجوزات حقيقية.</div>}<div className="detail-copy"><p className="eyebrow">TUESDAY SESSION</p><h1>{event.title}</h1><p className="detail-subtitle">{event.subtitle}</p><div className="detail-tags"><Pill tone={event.price_sar===0?'mint':'blue'}>{sar(event.price_sar)}</Pill><Pill tone="dark"><Clock size={13}/> {timeSA(event.starts_at)}</Pill></div><h2>عن الورشة</h2><p className="preline">{event.description||'سيتم نشر التفاصيل قريبًا.'}</p></div></div><aside className="booking-panel"><h3>تفاصيل اللقاء</h3><div className="booking-row"><CalendarDays/><div><small>الموعد</small><b>{dateLong(event.starts_at)}</b></div></div><div className="booking-row"><Clock/><div><small>الوقت</small><b>{timeSA(event.starts_at)} – {timeSA(event.ends_at)}</b></div></div><div className="booking-row"><Users/><div><small>المتحدث</small><b>{event.speaker||'سيعلن لاحقًا'}</b></div></div><div className="booking-row"><MapPin/><div><small>المكان</small><b>{event.venue_name||'سيعلن لاحقًا'}</b>{event.maps_url&&<a href={event.maps_url} target="_blank" rel="noopener noreferrer" className="inline-link">افتح خرائط Google <ExternalLink size={13}/></a>}</div></div><div className="booking-price"><span>قيمة التسجيل</span><strong>{sar(event.price_sar)}</strong></div>{done?<div className="success-box"><CheckCircle2/><b>تم استلام طلبك</b><p>بانتظار مراجعة الإدارة قبل إصدار التذكرة.</p><button className="btn btn-primary" onClick={()=>navigate('/account')}>متابعة طلبي</button></div>:<button disabled={busy} onClick={book} className="btn btn-primary wide">{busy?'جارٍ إرسال الطلب...':'اطلب حجز مقعدك'} <ArrowLeft size={18}/></button>}<small className="review-note"><ShieldCheck size={14}/> لا تصدر تذكرة حضور إلا بعد موافقة الإدارة، والتحقق من السداد للورش المدفوعة.</small>{message&&<div className="inline-error">{message}</div>}</aside></div></div>}
function LoginPage(){const {user}=useAuth();const [params]=useSearchParams();const navigate=useNavigate();const [email,setEmail]=useState('');const [name,setName]=useState('');const [otp,setOtp]=useState('');const [stage,setStage]=useState<'email'|'otp'>('email');const [busy,setBusy]=useState(false);const {notify,message}=useToast();const next=params.get('next')?.startsWith('/')&&!params.get('next')?.startsWith('//')?params.get('next')!:'/account';useEffect(()=>{if(user)navigate(next,{replace:true})},[user,navigate,next]);async function submit(e:FormEvent){e.preventDefault();if(!db){notify('اربط Supabase أولًا حتى تعمل حسابات المستخدمين');return}setBusy(true);if(stage==='email'){const {error}=await db.auth.signInWithOtp({email:email.trim(),options:{data:{full_name:name.trim()||'مشارك جديد'}}});if(error)notify(safeError(error));else {setStage('otp');notify('أرسلنا رسالة للتحقق. تأكد من بريدك، وقد تحتاج لفتح مجلد الرسائل غير المرغوبة.')}}else{const {error}=await db.auth.verifyOtp({email:email.trim(),token:otp.trim(),type:'email'});if(error)notify(safeError(error));else navigate(next,{replace:true})}setBusy(false)}return <div className="auth-page"><div className="auth-card"><div className="auth-icon"><Lock size={29}/></div><p className="eyebrow">WELCOME TO TUESDAY</p><h1>{stage==='email'?'ادخل عالم تيوزدية':'تأكيد البريد الإلكتروني'}</h1><p className="subtle">{stage==='email'?'حساب واحد لحجوزاتك وتذاكرك وسجل حضورك.':'أدخل رمز التحقق الذي وصلك عبر البريد الإلكتروني.'}</p><form onSubmit={submit} className="form-stack">{stage==='email'?<><label>الاسم الكامل <span className="label-hint">عند التسجيل لأول مرة</span><input value={name} maxLength={120} onChange={e=>setName(e.target.value)} placeholder="اسمك الكامل"/></label><label>البريد الإلكتروني<input type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label></>:<label>رمز التحقق<input required inputMode="numeric" autoComplete="one-time-code" value={otp} onChange={e=>setOtp(e.target.value)} placeholder="رمز مكون من 6 أرقام" minLength={6} maxLength={10}/></label>}<button className="btn btn-primary wide" disabled={busy}>{busy?'الرجاء الانتظار...':stage==='email'?'أرسل رمز الدخول':'تأكيد ودخول'} <ArrowLeft size={18}/></button>{stage==='otp'&&<button type="button" className="text-link centered" onClick={()=>setStage('email')}>تغيير البريد الإلكتروني</button>}</form>{message&&<div className="notice">{message}</div>}<p className="auth-footnote">هذه النسخة تعتمد تسجيل الدخول بالبريد الإلكتروني للتحقق. يمكن إضافة رسائل SMS لاحقًا بعد تفعيل مزود الرسائل.</p></div></div>}
function AccessGate({children,staff=false}:{children:ReactNode;staff?:boolean}){const {user,role,loading}=useAuth();const loc=useLocation();if(loading)return <div className="loading-page">جارٍ التحقق...</div>;if(!user)return <Navigate to={'/login?next='+encodeURIComponent(loc.pathname+loc.search)} replace/>;if(staff&&!role)return <div className="container page-pad"><Empty title="ليس لديك تصريح دخول لوحة الإدارة" desc="اطلب من صاحب المنصة تخصيص صلاحية لحسابك."/></div>;return <>{children}</>}
function AccountPage(){const {user,profile,refresh,signOut}=useAuth();const [name,setName]=useState(profile?.full_name??'');const [phone,setPhone]=useState(profile?.phone??'');const [bookings,setBookings]=useState<Booking[]>([]);const [tickets,setTickets]=useState<TicketData[]>([]);const [references,setReferences]=useState<Record<string,string>>({});const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const {notify,message}=useToast();const nav=useNavigate();useEffect(()=>{setName(profile?.full_name??'');setPhone(profile?.phone??'')},[profile]);const load=useCallback(async()=>{if(!db||!user)return;setLoading(true);const [b,t]=await Promise.all([db.from('bookings').select('*,events(*)').eq('user_id',user.id).order('created_at',{ascending:false}),db.from('tickets').select('*')]);setBookings((b.data??[]) as Booking[]);setTickets((t.data??[]) as TicketData[]);setLoading(false)},[user]);useEffect(()=>{void load()},[load]);async function saveProfile(e:FormEvent){e.preventDefault();if(!db||!user)return;setBusy(true);const {error}=await db.from('profiles').update({full_name:name.trim(),phone:phone.trim()}).eq('id',user.id);setBusy(false);notify(error?safeError(error):'تم تحديث ملفك الشخصي');if(!error)await refresh()}
 async function report(id:string){if(!db||!references[id]?.trim()){notify('أدخل رقم عملية الدفع المرجعي أولًا');return}setBusy(true);const {error}=await db.rpc('report_payment',{p_booking:id,p_reference:references[id].trim(),p_note:''});setBusy(false);notify(error?safeError(error):'تم إرسال بلاغ الدفع إلى الإدارة. لا يعتبر ذلك تأكيدًا بالسداد.');if(!error)void load()}
 return <div className="container page-pad"><PageHeader kicker="MY TUESDAY" title="حسابي وتذاكري" desc="هنا تتابع حالة طلباتك وتصل لتذاكر الحضور بعد الاعتماد."/><div className="account-layout"><aside className="profile-card"><div className="profile-circle"><UserRound size={30}/></div><h3>{profile?.full_name||user?.email}</h3><p>{user?.email}</p><form className="form-stack" onSubmit={saveProfile}><label>الاسم الكامل<input required minLength={2} maxLength={120} value={name} onChange={e=>setName(e.target.value)}/></label><label>رقم الجوال<input required inputMode="tel" type="tel" minLength={8} maxLength={24} value={phone} onChange={e=>setPhone(e.target.value)} placeholder="05xxxxxxxx"/></label><button disabled={busy} className="btn btn-outline wide" type="submit">حفظ بياناتي</button></form><button className="text-link logout" onClick={async()=>{await signOut();nav('/')}}><LogOut size={16}/> تسجيل الخروج</button></aside><section><div className="section-top"><h2>حجوزاتي <span className="count">{bookings.length}</span></h2><button className="mini-action" onClick={()=>void load()}><RefreshCw size={16}/> تحديث</button></div>{loading?<div className="skeleton"/>:bookings.length===0?<Empty title="ما عندك حجوزات لسه" desc="تصفح الورش واختر أول لقاء يناسبك."/>:bookings.map(b=>{const ticket=tickets.find(t=>t.booking_id===b.id);return <article className="my-booking" key={b.id}><div className="my-booking-head"><Pill tone={bookingTone(b.state)}>{bookingLabel(b.state)}</Pill><span className="small-muted">#{b.id.slice(0,8).toUpperCase()}</span></div><h3>{b.events?.title??'ورشة تيوزدية'}</h3><div className="booking-status-lines"><span>حالة الدفع: <b>{paymentLabel(b.payment_status)}</b></span><span>القيمة: <b>{sar(b.price_sar)}</b></span>{b.review_note&&<span>ملاحظة الإدارة: {b.review_note}</span>}</div>{b.state==='approved'&&ticket?<Link className="btn btn-sky wide" to={'/ticket/'+ticket.id}><TicketIcon size={18}/> عرض تذكرة QR</Link>:b.state==='awaiting_payment'||(b.state==='pending_review'&&b.payment_status==='reported')?<div className="payment-area">{b.payment_url_snapshot&&<a className="btn btn-outline wide" href={b.payment_url_snapshot} rel="noopener noreferrer" target="_blank">الانتقال إلى رابط الدفع الخارجي <ExternalLink size={16}/></a>}{b.payment_status!=='verified'&&<><small>بعد السداد، أدخل رقم العملية المرجعي. سيقوم الفريق بمطابقته مع سجل مزود الدفع.</small><div className="payment-ref"><input value={references[b.id]??''} maxLength={160} placeholder="الرقم المرجعي لعملية الدفع" onChange={e=>setReferences(v=>({...v,[b.id]:e.target.value}))}/><button className="btn btn-primary" onClick={()=>void report(b.id)} disabled={busy}>إرسال</button></div></>}</div>:null}</article>})}</section></div>{message&&<div className="floating-message">{message}</div>}</div>}
function TicketPage(){const {id}=useParams();const {user}=useAuth();const [ticket,setTicket]=useState<TicketData|null>(null);const [event,setEvent]=useState<EventData|null>(null);const [code,setCode]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);useEffect(()=>{let active=true;async function run(){if(!db||!id)return;const {data,error:e}=await db.from('tickets').select('*,bookings!inner(*,events(*))').eq('id',id).single();if(!active)return;if(e||!data){setError('لم نتمكن من العثور على التذكرة');setLoading(false);return}setTicket(data as TicketData);const inner=data.bookings as unknown as Booking;setEvent(inner.events??null);try{const res=await fetch('/api/ticket?ticket_id='+encodeURIComponent(id),{headers:await authHeader(user)});const payload=await res.json() as {code?:string;error?:string};if(!res.ok)throw new Error(payload.error||'تعذر إنشاء رمز التذكرة');if(active)setCode(payload.code??'')}catch(err){if(active)setError(safeError(err))}finally{if(active)setLoading(false)}}void run();return()=>{active=false}},[id,user]);return <div className="container page-pad ticket-page"><Link to="/account" className="back-link"><ArrowRight size={18}/> حجوزاتي</Link><PageHeader kicker="YOUR TICKET" title="تذكرتك الرقمية" desc="اعرض هذه الشاشة لموظف الاستقبال عند دخول الورشة."/>{loading?<div className="skeleton"/>:error?<div className="warn-box">{error}</div>:<article className="digital-ticket"><div className="ticket-top"><img src="/logo.webp" alt="تيوزدية"/><Pill tone={ticket?.state==='used'?'wait':'mint'}>{ticket?.state==='used'?'تم استخدام التذكرة':'جاهزة للدخول'}</Pill><h2>{event?.title||'ورشة تيوزدية'}</h2><span>{event?.starts_at?dateLong(event.starts_at):''} • {event?.starts_at?timeSA(event.starts_at):''}</span></div><div className="ticket-rip"/><div className="ticket-qr"><div className="qr-white">{code&&<QRCodeSVG value={code} size={224} includeMargin={true} level="H"/>}</div><p>{ticket?.state==='used'?'تم تسجيل حضورك سابقًا. لا يمكن استخدام التذكرة مجددًا.':'يُسمح بالدخول مرة واحدة. احتفظ برمز QR في حسابك.'}</p><code>#{ticket?.id.slice(0,8).toUpperCase()}</code></div></article>}</div>}
function AboutPage(){return <div className="container page-pad"><PageHeader kicker="ABOUT TUESDAY" title="مجتمع تيوزدية ريادة الأعمال" desc="كل لقاء فرصة لاكتشاف فكرة، وتعلّم مهارة، والتعرّف على أشخاص يشاركونك الطموح."/><div className="about-hero"><img src="/logo.webp" alt="شعار تيوزدية"/><h2>نؤمن أن الفرص تبدأ من لقاء.</h2><p>تيوزدية مجتمع يجمع رواد الأعمال والمهتمين بالبزنس في لقاءات وورش حوارية وعملية. هدفنا أن تتحول المعرفة إلى خطوة ملموسة في طريق المشروع.</p></div><div className="feature-grid"><div className="info-card"><Sparkles/><h3>الإلهام</h3><p>أفكار وتجارب تفتح طرقًا جديدة.</p></div><div className="info-card"><Users/><h3>العلاقات</h3><p>تواصل حقيقي بين أفراد المجتمع.</p></div><div className="info-card"><BookOpen/><h3>المعرفة</h3><p>مهارات عملية من ورش متخصصة.</p></div></div></div>}
function PrivacyPage(){return <div className="container page-pad legal"><PageHeader title="الخصوصية وشروط الحجز"/><h2>مسودة سياسة تشغيلية — تتطلب اعتماد صاحب المنصة قبل الإطلاق</h2><p>نجمع الاسم والبريد ورقم الجوال من أجل إدارة الحسابات والحجوزات والتواصل بشأن الورش. يُحفظ تاريخ المراجعة والحضور لأغراض التشغيل والتدقيق وفق سياسة الاحتفاظ المعتمدة. يمكن التواصل مع الإدارة لطلب تحديث البيانات أو الاستفسار عنها.</p><p>لا يعني الضغط على رابط الدفع اعتماد الحجز. لا تصدر تذكرة الدخول حتى تتحقق إدارة تيوزدية من الدفع (للفعاليات المدفوعة) وتعتمد الطلب. تذكرة QR صالحة للدخول مرة واحدة فقط.</p><p>يجب على إدارة المنصة نشر سياسة إلغاء واسترداد معتمدة، ووسائل تواصل رسمية، وسياسة احتفاظ وحذف للبيانات قبل استقبال المدفوعات الفعلية.</p></div>}

type PaymentSubmission={id:string;booking_id:string;reference:string;note:string;status:string;created_at:string;verified_at:string|null};
type CheckinData={id:string;event_id:string;booking_id:string;checked_in_at:string;staff_user_id:string};
type RefundCase={id:string;booking_id:string;status:string;reason:string;created_at:string;completed_at:string|null};
type AdminTab='dashboard'|'events'|'requests'|'scanner'|'export'|'team';
function AdminPage(){const {role}=useAuth();const [search,setSearch]=useSearchParams();const tab=(search.get('tab')||'dashboard') as AdminTab;const selectTab=(t:AdminTab)=>setSearch({tab:t});const [events,setEvents]=useState<EventData[]>([]);const [bookings,setBookings]=useState<Booking[]>([]);const [payments,setPayments]=useState<PaymentSubmission[]>([]);const [refunds,setRefunds]=useState<RefundCase[]>([]);const [staff,setStaff]=useState<{user_id:string;role:string;active:boolean;full_name?:string;email?:string}[]>([]);const [checkins,setCheckins]=useState<CheckinData[]>([]);const [busy,setBusy]=useState(false);const [editing,setEditing]=useState<EventData|null|undefined>(undefined);const {notify,message}=useToast();const [lastRefresh,setLastRefresh]=useState<Date|null>(null);
 const load=useCallback(async()=>{if(!db)return;const [e,b,p,c,r]=await Promise.all([db.from('events').select('*').order('starts_at',{ascending:false}),db.from('bookings').select('*,events(*),profiles(*)').order('created_at',{ascending:false}),db.from('payment_submissions').select('*').order('created_at',{ascending:false}),db.from('checkins').select('*').order('checked_in_at',{ascending:false}),db.from('refund_cases').select('*').order('created_at',{ascending:false})]);setEvents((e.data??[]) as EventData[]);setBookings((b.data??[]) as Booking[]);setPayments((p.data??[]) as PaymentSubmission[]);setCheckins((c.data??[]) as CheckinData[]);setRefunds((r.data??[]) as RefundCase[]);const {data:staffRows}=await db.from('staff_members').select('user_id,role,active');const members=(staffRows??[]) as {user_id:string;role:string;active:boolean}[];const ids=members.map(x=>x.user_id);const {data:staffProfiles}=ids.length?await db.from('profiles').select('id,full_name,email').in('id',ids):{data:[] as {id:string;full_name:string;email:string}[]};setStaff(members.map(m=>({...m,...(staffProfiles??[]).find(p=>p.id===m.user_id)})));setLastRefresh(new Date());},[]);
 useEffect(()=>{void load();const timer=setInterval(()=>{void load()},30000);const onFocus=()=>void load();window.addEventListener('focus',onFocus);return()=>{clearInterval(timer);window.removeEventListener('focus',onFocus)}},[load]);
 const awaiting=bookings.filter(b=>['pending_review','needs_info'].includes(b.state));const paidWaiting=awaiting.filter(b=>b.price_sar>0&&b.payment_status!=='verified');
 async function verifyPayment(id:string){if(!db)return;if(!window.confirm('تأكيد: هل تحققت بنفسك من مرجع العملية ومبلغها وعملتها في حساب مزود الدفع؟'))return;setBusy(true);const {error}=await db.rpc('verify_payment',{p_submission:id});setBusy(false);notify(error?safeError(error):'تم توثيق التحقق من عملية الدفع');void load();}
 async function decide(id:string,decision:'approve'|'reject'|'needs_info',note:string){if(!db)return;if(!window.confirm(decision==='approve'?'هل تؤكد اعتماد الحجز وإصدار تذكرته؟':'هل تؤكد حفظ قرار المراجعة؟'))return;setBusy(true);const {error}=await db.rpc('decide_booking',{p_booking:id,p_decision:decision,p_note:note});setBusy(false);notify(error?safeError(error):'تم حفظ قرار المراجعة');void load();}
 async function confirmRefund(id:string){if(!db)return;if(!window.confirm('هل تم تنفيذ الاسترداد فعليًا في بوابة الدفع وتحققت منه؟'))return;const {error}=await db.rpc('confirm_refund',{p_case:id});notify(error?safeError(error):'تم توثيق الاسترداد في النظام');if(!error)void load()}
 async function exportExcel(){if(!db||role!=='owner'&&role!=='admin')return;setBusy(true);try{const ExcelJS=(await import('exceljs')).default;const wb=new ExcelJS.Workbook();wb.creator='Tuesday Entrepreneurship';const safe=(v:unknown)=>{const s=String(v??'');return /^[=+@\-\t\r]/.test(s)?"'"+s:s};function sheet(name:string,heads:string[],rows:unknown[][]){const w=wb.addWorksheet(name,{views:[{state:'frozen',ySplit:1}]});w.addRow(heads);w.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};w.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF0B1726'}};w.getRow(1).alignment={vertical:'middle'};for(const row of rows)w.addRow(row.map(safe));w.columns=heads.map((h,i)=>({width:Math.min(45,Math.max(16,h.length*2+3,...rows.slice(0,40).map(r=>Math.min(38,String(r[i]??'').length+2))))}));w.autoFilter={from:'A1',to:{row:Math.max(1,rows.length+1),column:heads.length}};w.properties.defaultRowHeight=19;}
 sheet('الحجوزات',['رقم الحجز','الورشة','المشارك','البريد','الجوال','الحالة','الدفع','السعر ر.س','تاريخ الإنشاء','ملاحظة الإدارة'],bookings.map(b=>[b.id,b.events?.title,b.profiles?.full_name,b.profiles?.email,b.profiles?.phone,bookingLabel(b.state),paymentLabel(b.payment_status),b.price_sar,b.created_at,b.review_note]));
 sheet('الحضور',['رقم الحضور','رقم الحجز','الورشة','المشارك','وقت الحضور','معرف موظف الاستقبال'],checkins.map(c=>{const b=bookings.find(x=>x.id===c.booking_id);return [c.id,c.booking_id,b?.events?.title,b?.profiles?.full_name,c.checked_in_at,c.staff_user_id]}));
 sheet('تأكيدات الدفع',['الحجز','المرجع','الحالة','تاريخ الطلب','تم التحقق في'],payments.map(p=>[p.booking_id,p.reference,p.status,p.created_at,p.verified_at]));
 sheet('الاستردادات',['رقم الحجز','الحالة','السبب','تاريخ الإنشاء','تاريخ الإكمال'],refunds.map(r=>[r.booking_id,r.status,r.reason,r.created_at,r.completed_at]));
 sheet('الورش',['المعرف','العنوان','الموعد','المكان','المقاعد','السعر','الحالة'],events.map(e=>[e.id,e.title,e.starts_at,e.venue_name,e.capacity,e.price_sar,e.status]));
 const buffer=await wb.xlsx.writeBuffer();const blob=new Blob([new Uint8Array(buffer)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`Tuesday-Reports-${new Date().toISOString().slice(0,10)}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);notify('تم إعداد وتصدير ملف Excel من البيانات الحالية.');
 }catch(e){notify('تعذر تصدير Excel: '+safeError(e))}finally{setBusy(false)}}
 const adminTabs:{key:AdminTab;label:string;icon:ReactNode}[]=[{key:'dashboard',label:'الرئيسية',icon:<LayoutDashboard/>},{key:'events',label:'الورش',icon:<CalendarDays/>},{key:'requests',label:'المراجعات',icon:<ClipboardCheck/>},{key:'scanner',label:'الماسح',icon:<ScanLine/>},{key:'export',label:'التقارير',icon:<FileSpreadsheet/>},...(role==='owner'?[{key:'team' as AdminTab,label:'الفريق',icon:<Users/>}]:[])];return <div className="container page-pad"><div className="admin-header"><div><span className="eyebrow">TUESDAY CONTROL</span><h1>لوحة إدارة تيوزدية</h1><p>ورش، طلبات، حضور — كل شيء في مكان واحد.</p></div><button className="btn btn-outline" onClick={()=>void load()}><RefreshCw size={17}/> تحديث</button></div><div className="admin-tabs">{adminTabs.map(t=><button key={t.key} className={tab===t.key?'active':''} onClick={()=>{setEditing(undefined);selectTab(t.key)}}>{t.icon}<span>{t.label}</span>{t.key==='requests'&&awaiting.length>0&&<i>{awaiting.length}</i>}</button>)}</div>
 {tab==='dashboard'&&<><div className="dashboard-kpis"><div className="kpi"><div className="kpi-icon"><CalendarDays/></div><span>إجمالي الورش</span><strong>{events.length}</strong></div><div className="kpi"><div className="kpi-icon"><ClipboardCheck/></div><span>بانتظار المراجعة</span><strong>{awaiting.length}</strong></div><div className="kpi"><div className="kpi-icon"><Users/></div><span>الحجوزات المعتمدة</span><strong>{bookings.filter(b=>b.state==='approved').length}</strong></div><div className="kpi"><div className="kpi-icon"><ScanLine/></div><span>الحضور المسجل</span><strong>{checkins.length}</strong></div></div><div className="admin-panels"><div className="white-panel"><div className="panel-heading"><h2>الطلبات الأخيرة</h2><button className="text-link" onClick={()=>selectTab('requests')}>عرض الكل <ArrowLeft size={16}/></button></div>{bookings.slice(0,5).map(b=><div key={b.id} className="dashboard-row"><div><b>{b.profiles?.full_name||'مشارك'}</b><small>{b.events?.title||'ورشة'}</small></div><Pill tone={bookingTone(b.state)}>{bookingLabel(b.state)}</Pill></div>)}{bookings.length===0&&<Empty title="لا توجد حجوزات حتى الآن"/>}</div><div className="white-panel"><h2>نظرة سريعة</h2><div className="summary-line"><span>طلبات دفع تحتاج تحققًا</span><b>{paidWaiting.length}</b></div><div className="summary-line"><span>استردادات قيد التنفيذ</span><b>{refunds.filter(r=>r.status==='pending').length}</b></div><div className="summary-line"><span>حجوزات قيد المراجعة</span><b>{awaiting.length}</b></div><div className="summary-line"><span>نسبة حضور المعتمدين</span><b>{bookings.filter(b=>b.state==='approved').length?Math.round(checkins.length/bookings.filter(b=>b.state==='approved').length*100):0}%</b></div><div className="summary-line"><span>آخر تحديث للبيانات</span><b>{lastRefresh?.toLocaleTimeString('ar-SA')||'—'}</b></div><button className="btn btn-primary wide" onClick={()=>{selectTab('events');setEditing(null)}}><Plus size={18}/> إضافة ورشة</button></div></div></>}
 {tab==='events'&&(editing!==undefined?<EventEditor event={editing} onClose={()=>setEditing(undefined)} onSaved={()=>{setEditing(undefined);void load()}} notify={notify}/>:<div className="white-panel"><div className="panel-heading"><h2>إدارة الورش <span className="count">{events.length}</span></h2>{(role==='owner'||role==='admin')&&<button className="btn btn-primary" onClick={()=>setEditing(null)}><Plus size={17}/> ورشة جديدة</button>}</div><div className="admin-event-list">{events.map(e=><div className="admin-event" key={e.id}><div className="admin-event-avatar"><CalendarDays/></div><div className="grow"><b>{e.title}</b><span>{dateLong(e.starts_at)} • {sar(e.price_sar)}</span></div><Pill tone={e.status==='published'?'ok':'wait'}>{e.status==='published'?'منشورة':e.status==='draft'?'مسودة':e.status==='cancelled'?'ملغاة':'مغلقة'}</Pill>{(role==='owner'||role==='admin')&&<button className="icon-button" aria-label="تعديل الورشة" onClick={()=>setEditing(e)}><ArrowUpLeft size={19}/></button>}</div>)}{events.length===0&&<Empty title="ابدأ بإضافة أول ورشة"/>}</div></div>)}
 {tab==='requests'&&<div className="white-panel"><div className="panel-heading"><h2>سجل الطلبات والمراجعة</h2><Pill tone="wait">{awaiting.length} تنتظر المراجعة</Pill></div>{bookings.length===0?<Empty title="ما وصلتنا طلبات بعد"/>:bookings.map(b=><ReviewCard key={b.id} booking={b} payments={payments.filter(p=>p.booking_id===b.id)} onVerify={verifyPayment} onDecide={decide} busy={busy}/>)}{refunds.length>0&&<div className="refunds-block"><h3>طلبات الاسترداد بعد الرفض</h3><p className="subtle">نفّذ الاسترداد أولًا من لوحة مزود الدفع، ثم أكد العملية هنا.</p>{refunds.map(r=><div className="dashboard-row" key={r.id}><div><b>حجز #{r.booking_id.slice(0,8)}</b><small>{r.status==='pending'?'يحتاج تنفيذ الاسترداد':'مكتمل'}</small></div>{r.status==='pending'&&(role==='owner'||role==='admin')?<button className="btn btn-mini btn-outline" onClick={()=>void confirmRefund(r.id)}>تأكيد الاسترداد الفعلي</button>:<Pill tone="mint">مكتمل</Pill>}</div>)}</div>}</div>}
 {tab==='scanner'&&<Scanner notify={notify}/>}
 {tab==='team'&&role==='owner'&&<StaffManager staff={staff} onUpdated={()=>void load()} notify={notify}/>}
 {tab==='export'&&<div className="white-panel"><div className="panel-heading"><h2>التقارير وتصدير البيانات</h2><Pill>Excel XLSX</Pill></div><p className="subtle">يحتوي الملف على أوراق منفصلة للحجوزات والحضور وتأكيدات الدفع والورش. بيانات التقارير لا تُتاح إلا لصاحب المنصة أو المدير.</p><div className="dashboard-kpis"><div className="kpi"><span>الحجوزات</span><strong>{bookings.length}</strong></div><div className="kpi"><span>الحضور</span><strong>{checkins.length}</strong></div><div className="kpi"><span>طلبات السداد</span><strong>{payments.length}</strong></div><div className="kpi"><span>الورش</span><strong>{events.length}</strong></div></div><button className="btn btn-primary" onClick={()=>void exportExcel()} disabled={busy||!(role==='owner'||role==='admin')}><Download size={18}/> {busy?'يُجهز الملف...':'تنزيل تقرير Excel كامل'}</button>{role!=='owner'&&role!=='admin'&&<div className="warn-box">ليس لديك إذن تصدير تقارير البيانات.</div>}</div>}
 {message&&<div className="floating-message" role="status">{message}</div>}</div>}
function ReviewCard({booking:b,payments,onVerify,onDecide,busy}:{booking:Booking;payments:PaymentSubmission[];onVerify:(id:string)=>Promise<void>;onDecide:(id:string,decision:'approve'|'reject'|'needs_info',note:string)=>Promise<void>;busy:boolean}){const [open,setOpen]=useState(false);const [note,setNote]=useState('');return <div className="review-card"><div className="review-head"><div><strong>{b.profiles?.full_name||'مشارك'}</strong><small>{b.events?.title||'ورشة'}</small></div><Pill tone={bookingTone(b.state)}>{bookingLabel(b.state)}</Pill></div><div className="review-stats"><span>السعر: <b>{sar(b.price_sar)}</b></span><span>الدفع: <b>{paymentLabel(b.payment_status)}</b></span><span>التاريخ: {new Date(b.created_at).toLocaleDateString('ar-SA')}</span></div><button className="mini-action" onClick={()=>setOpen(!open)}>{open?'إغلاق التفاصيل':'عرض التفاصيل والمراجعة'} <ChevronLeft size={16}/></button>{open&&<div className="review-expanded"><div className="review-field"><b>البريد</b><span>{b.profiles?.email||'—'}</span></div><div className="review-field"><b>الجوال</b><span dir="ltr">{b.profiles?.phone||'—'}</span></div><div className="review-field"><b>رقم الحجز</b><span dir="ltr">{b.id}</span></div>{b.review_note&&<div className="notice">ملاحظة سابقة: {b.review_note}</div>}{payments.length>0&&<div className="payment-review"><h4>مراجع الدفع المرسلة</h4>{payments.map(p=><div className="payment-review-row" key={p.id}><div><b>{p.reference}</b><small>{p.status==='verified'?'متحقق منه':p.status==='reported'?'بانتظار مطابقة':'مرفوض'}</small></div>{p.status==='reported'&&<button className="btn btn-outline btn-mini" disabled={busy} onClick={()=>void onVerify(p.id)}><ShieldCheck size={14}/> تأكيد بعد المطابقة</button>}</div>)}</div>} {['pending_review','needs_info'].includes(b.state)&&<><label>ملاحظة المراجع<textarea value={note} maxLength={1000} onChange={e=>setNote(e.target.value)} rows={2} placeholder="سبب القرار أو ملاحظات مهمة..."/></label><div className="review-actions"><button disabled={busy||(b.price_sar>0&&b.payment_status!=='verified')} className="btn btn-approve" onClick={()=>void onDecide(b.id,'approve',note)}><Check size={16}/> اعتماد وإصدار تذكرة</button><button disabled={busy||!note.trim()} className="btn btn-outline" onClick={()=>void onDecide(b.id,'needs_info',note)}>طلب استكمال</button><button disabled={busy||!note.trim()} className="btn btn-danger" onClick={()=>void onDecide(b.id,'reject',note)}>رفض</button></div>{b.price_sar>0&&b.payment_status!=='verified'&&<small className="warning-inline"><AlertTriangle size={14}/> لا يمكن الموافقة قبل مطابقة الدفع والتحقق منه.</small>}</>}</div>}</div>}
function EventEditor({event,onClose,onSaved,notify}:{event:EventData|null;onClose:()=>void;onSaved:()=>void;notify:(v:string)=>void}){const [form,setForm]=useState({title:event?.title??'',slug:event?.slug??'',subtitle:event?.subtitle??'',description:event?.description??'',speaker:event?.speaker??'',image_url:event?.image_url??'',venue_name:event?.venue_name??'',maps_url:event?.maps_url??'',starts_at:event?localSaudi(event.starts_at):'',ends_at:event?localSaudi(event.ends_at):'',capacity:event?.capacity??40,price_sar:event?.price_sar??0,payment_url:event?.payment_url??'',status:event?.status??'draft'});const [busy,setBusy]=useState(false);const [file,setFile]=useState<File|null>(null);const set=(key:keyof typeof form,value:string|number)=>setForm(p=>({...p,[key]:value}));async function save(e:FormEvent){e.preventDefault();if(!db)return;if(form.price_sar>0&&!form.payment_url.trim()){notify('أدخل رابط دفع HTTPS للورشة المدفوعة');return}if(new Date(asSaudiUTC(form.ends_at))<=new Date(asSaudiUTC(form.starts_at))){notify('وقت النهاية يجب أن يكون بعد البداية');return}if(form.maps_url&&!(form.maps_url.startsWith('https://'))){notify('يجب أن يبدأ رابط الخريطة بـ https://');return}setBusy(true);let image=form.image_url;try{if(file){const name=`${crypto.randomUUID()}.${file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg'}`;const upload=await db.storage.from('event-images').upload(name,file,{contentType:file.type,cacheControl:'3600'});if(upload.error)throw upload.error;image=db.storage.from('event-images').getPublicUrl(name).data.publicUrl}const payload={title:form.title.trim(),slug:form.slug.trim().toLowerCase(),subtitle:form.subtitle.trim(),description:form.description.trim(),speaker:form.speaker.trim(),image_url:image||null,venue_name:form.venue_name.trim(),maps_url:form.maps_url||null,starts_at:asSaudiUTC(form.starts_at),ends_at:asSaudiUTC(form.ends_at),capacity:Number(form.capacity),price_sar:Number(form.price_sar),payment_url:form.price_sar>0?form.payment_url.trim():null,status:form.status};const result=event?await db.from('events').update(payload).eq('id',event.id):await db.from('events').insert(payload);if(result.error)throw result.error;notify('تم حفظ الورشة بنجاح');onSaved()}catch(err){notify('تعذر حفظ الورشة: '+safeError(err))}finally{setBusy(false)}}return <div className="white-panel"><div className="panel-heading"><h2>{event?'تعديل الورشة':'إضافة ورشة جديدة'}</h2><button className="mini-action" onClick={onClose}><X size={17}/> إغلاق</button></div><form onSubmit={save} className="event-form"><label>عنوان الورشة<input required minLength={5} maxLength={180} value={form.title} onChange={e=>set('title',e.target.value)} placeholder="عنوان واضح وجذاب"/></label><label>الرابط المختصر (إنجليزي)<input required pattern="[a-z0-9]+(-[a-z0-9]+)*" value={form.slug} onChange={e=>set('slug',e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,''))} placeholder="workshop-name"/></label><label className="full">وصف قصير<input value={form.subtitle} onChange={e=>set('subtitle',e.target.value)} placeholder="تعريف مختصر يظهر في البطاقة"/></label><label className="full">التفاصيل ومحاور الورشة<textarea rows={5} value={form.description} onChange={e=>set('description',e.target.value)} placeholder="ما الذي سيتعلمه المشارك؟"/></label><label>اسم المتحدث<input value={form.speaker} onChange={e=>set('speaker',e.target.value)} placeholder="عمرو الفران"/></label><label>اسم المكان<input value={form.venue_name} onChange={e=>set('venue_name',e.target.value)} placeholder="اسم قاعة اللقاء"/></label><label>وقت البداية (بتوقيت السعودية)<input type="datetime-local" required value={form.starts_at} onChange={e=>set('starts_at',e.target.value)}/></label><label>وقت النهاية (بتوقيت السعودية)<input type="datetime-local" required value={form.ends_at} onChange={e=>set('ends_at',e.target.value)}/></label><label>عدد المقاعد<input type="number" min="1" max="50000" required value={form.capacity} onChange={e=>set('capacity',Number(e.target.value))}/></label><label>السعر (0 = مجانية)<input type="number" min="0" step="0.01" required value={form.price_sar} onChange={e=>set('price_sar',Number(e.target.value))}/></label><label className="full">رابط الموقع في خرائط Google<input type="url" value={form.maps_url??''} onChange={e=>set('maps_url',e.target.value)} placeholder="https://maps.google.com/..."/></label>{form.price_sar>0&&<label className="full">رابط الدفع (HTTPS)<input required type="url" value={form.payment_url??''} onChange={e=>set('payment_url',e.target.value)} placeholder="https://payment-provider.example/..."/><small>رابط خارجي؛ يجب أن تتأكد الإدارة يدويًا من السداد قبل الاعتماد.</small></label>}<label className="full">صورة الإعلان (JPEG / PNG / WebP، حد 5MB)<span className="file-upload"><ImagePlus size={24}/>{file?file.name:'اختر صورة من جوالك أو جهازك'}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const f=e.target.files?.[0];if(f){if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){notify('اختر صورة بصيغة صحيحة وحجم أقل من 5MB');return}setFile(f)}}}/></span></label><label>حالة النشر<select value={form.status} onChange={e=>set('status',e.target.value)}><option value="draft">مسودة</option><option value="published">منشورة</option><option value="closed">التسجيل مغلق</option><option value="cancelled">ملغاة</option></select></label><div className="full form-actions"><button className="btn btn-primary" disabled={busy}><Check size={17}/> {busy?'يُحفظ الآن...':'حفظ الورشة'}</button><button type="button" className="btn btn-outline" onClick={onClose}>إلغاء</button></div></form></div>}
function Scanner({notify}:{notify:(s:string)=>void}){const {user}=useAuth();const [scanning,setScanning]=useState(false);const [manual,setManual]=useState('');const [result,setResult]=useState<{ok:boolean;reason?:string;name?:string;event?:string;used_at?:string}|null>(null);const [busy,setBusy]=useState(false);const reader=useRef<{stop:()=>Promise<void>;clear:()=>void}|null>(null);const inFlight=useRef(false);const scan=useCallback(async(code:string)=>{if(inFlight.current)return;inFlight.current=true;setBusy(true);setResult(null);try{const res=await fetch('/api/checkin',{method:'POST',headers:{'Content-Type':'application/json',...(await authHeader(user))},body:JSON.stringify({code})});const data=await res.json() as {ok:boolean;reason?:string;error?:string;name?:string;event?:string;used_at?:string};if(!res.ok)throw new Error(data.error||'تعذر التحقق');setResult(data)}catch(e){notify(safeError(e))}finally{setBusy(false);inFlight.current=false}},[notify,user]);const stop=useCallback(async()=>{if(reader.current){try{await reader.current.stop()}catch{}try{reader.current.clear()}catch{}reader.current=null}setScanning(false)},[]);async function start(){setResult(null);setScanning(true);try{const {Html5Qrcode}=await import('html5-qrcode');const scanner=new Html5Qrcode('qr-camera',{verbose:false});reader.current=scanner;await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},async decoded=>{if(!inFlight.current){await stop();await scan(decoded)}},()=>{})}catch(e){setScanning(false);notify('تعذر تشغيل الكاميرا، اسمح بالوصول إليها أو استخدم الإدخال اليدوي. '+safeError(e))}}useEffect(()=>()=>{void stop()},[stop]);const reason:Record<string,string>={ALREADY_USED:'تم تسجيل حضور هذه التذكرة مسبقًا',INVALID_CODE:'رمز QR غير صالح أو تم تعديله',OUTSIDE_WINDOW:'الحضور غير متاح في هذا الوقت',INVALID_STATE:'الحجز أو التذكرة غير صالح للدخول',NOT_FOUND:'التذكرة غير موجودة'};return <div className="white-panel scanner-panel"><div className="panel-heading"><h2>ماسح حضور الورش</h2><Pill tone="mint"><ShieldCheck size={14}/> تحقق آمن</Pill></div><p className="subtle">امسح QR الخاص بالمشارك. يتحقق الخادم من التوقيع وصلاحية التذكرة ويسجل دخولًا واحدًا فقط.</p><div id="qr-camera" className={scanning?'camera-frame show':'camera-frame'}>{!scanning&&<><ScanLine size={56}/><b>جاهز لمسح التذكرة</b><p>استخدم كاميرا جهاز الاستقبال</p></>}</div><button className="btn btn-primary wide" disabled={busy} onClick={scanning?()=>void stop():()=>void start()}><Camera size={18}/>{scanning?'إيقاف الكاميرا':'فتح الكاميرا ومسح QR'}</button><div className="manual-scan"><label>أو أدخل محتوى التذكرة يدويًا للتشخيص<input value={manual} onChange={e=>setManual(e.target.value)} placeholder="TUE1.xxxxx..." autoComplete="off"/></label><button className="btn btn-outline" disabled={!manual.trim()||busy} onClick={()=>void scan(manual)}>تحقق</button></div>{busy&&<p className="notice">جارٍ التحقق في قاعدة البيانات...</p>}{result&&<div className={'scan-result '+(result.ok?'scan-success':'scan-reject')}>{result.ok?<CheckCircle2 size={42}/>:<AlertTriangle size={42}/>}<h3>{result.ok?'تم تسجيل الحضور بنجاح':reason[result.reason??'']??'لم يُقبل الرمز'}</h3>{result.name&&<p>{result.name}</p>}{result.event&&<p>{result.event}</p>}<small>{result.ok?'تم حفظ حضور واحد في قاعدة البيانات':'لم يُنشأ سجل حضور إضافي'}</small></div>}</div>}
function StaffManager({staff,onUpdated,notify}:{staff:{user_id:string;role:string;active:boolean;full_name?:string;email?:string}[];onUpdated:()=>void;notify:(s:string)=>void}){const [email,setEmail]=useState('');const [role,setRole]=useState('checkin');const [busy,setBusy]=useState(false);async function assign(e:FormEvent){e.preventDefault();if(!db)return;setBusy(true);const {error}=await db.rpc('set_staff_role',{p_email:email.trim().toLowerCase(),p_role:role,p_active:true});setBusy(false);if(error)notify(safeError(error));else{notify('تم حفظ صلاحية الموظف');setEmail('');onUpdated()}}async function toggle(member:{email?:string;role:string;active:boolean}){if(!member.email||!db)return;if(!window.confirm(member.active?'إيقاف صلاحية هذا العضو؟':'إعادة تفعيل صلاحية العضو؟'))return;const {error}=await db.rpc('set_staff_role',{p_email:member.email,p_role:member.role,p_active:!member.active});notify(error?safeError(error):'تم تحديث صلاحية العضو');if(!error)onUpdated()}return <div className="white-panel"><h2>صلاحيات الفريق</h2><p className="subtle">يمكن تعيين صلاحية لحساب مسجل مسبقًا فقط. مدير المنصة هو المسؤول عن منح أو إيقاف الصلاحيات.</p><form className="staff-form" onSubmit={assign}><label>بريد الموظف المسجل<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="member@example.com"/></label><label>الصلاحية<select value={role} onChange={e=>setRole(e.target.value)}><option value="checkin">الاستقبال ومسح التذاكر</option><option value="reviewer">مراجع الحجوزات والمدفوعات</option><option value="admin">مدير محتوى وتقارير</option><option value="owner">مالك</option></select></label><button className="btn btn-primary" disabled={busy}><Plus size={17}/> حفظ الصلاحية</button></form><div className="staff-list">{staff.map(m=><div className="admin-event" key={m.user_id}><div className="admin-event-avatar"><Users/></div><div className="grow"><b>{m.full_name||m.email||m.user_id}</b><span>{m.email} • {m.role}</span></div><Pill tone={m.active?'mint':'bad'}>{m.active?'نشط':'معطل'}</Pill><button className="btn btn-mini btn-outline" onClick={()=>void toggle(m)}>{m.active?'تعطيل':'تفعيل'}</button></div>)}</div></div>}
function NotFound(){return <div className="container page-pad"><Empty title="الصفحة غير موجودة"/><Link className="btn btn-primary" to="/">العودة للرئيسية</Link></div>}
export default function App(){return <AuthProvider><Shell><Routes><Route path="/" element={<HomePage/>}/><Route path="/events" element={<EventsPage/>}/><Route path="/events/:slug" element={<EventDetailPage/>}/><Route path="/login" element={<LoginPage/>}/><Route path="/account" element={<AccessGate><AccountPage/></AccessGate>}/><Route path="/ticket/:id" element={<AccessGate><TicketPage/></AccessGate>}/><Route path="/admin" element={<AccessGate staff><AdminPage/></AccessGate>}/><Route path="/about" element={<AboutPage/>}/><Route path="/privacy" element={<PrivacyPage/>}/><Route path="*" element={<NotFound/>}/></Routes></Shell></AuthProvider>}
